import{z as n,x as s,o as B,c as l,q as e,j as t,D as a,d as r,s as o,S as i}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"分布式回测架构","description":"","frontmatter":{"title":"分布式回测架构","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/de-distributed-backtest.md","filePath":"quant/de-distributed-backtest.md","lastUpdated":1791413859000}'),d={name:"quant/de-distributed-backtest.md"};function C(h,E,p,D,c,u){const A=s("Mermaid");return B(),l("div",null,[E[2]||(E[2]=e('<h1 id="分布式回测架构" tabindex="-1">分布式回测架构 <a class="header-anchor" href="#分布式回测架构" aria-label="Permalink to &quot;分布式回测架构&quot;">​</a></h1><div class="epigraph"><p>参数扫描的并行度不是引擎给的，是数据给的：数据不可变，任务才能随便挪；数据会漂，集群只会更快地生产互相矛盾的回测。</p><footer>—— 据 Amdahl, Validity of the Single-Processor Approach, AFIPS 1967；与站内点时数据库的不可变口径整理</footer></div><p><a href="/quant/de-pointintime-db">上一课</a>把「任一决策日的数据视图」做成全平台唯一的 as-of 函数；本课处理这个函数被成千上万个回测任务并发调用时的架构。单个回测是研究，参数扫描、走窗验证与批量消融是生产。<a href="/quant/backtest-vectorization">回测向量化</a>讲过单引擎的形状选择，本课讲集群层：怎么切任务、怎么共享数据、怎么让一万个结果仍可比。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>分布式回测的第一错误不是慢，是漂。worker 各自拉「最新数据」，任务排队几小时，队头队尾看到的数据集已经不同——同一批实验内部口径不一致，比较失去意义。<span class="marginnote">直觉类比：数据漂就像考试开考两小时后悄悄换了教材——先做的考生和后做的考生答的不是同一套题，最后比分数毫无意义。钉住数据版本，等于给全体考生发同一版教材的复印件。</span>第二错误是边界：按时间切段时，持有期跨过段界的收益要么丢失要么重复计入；按标的截面切时，组合层的约束（行业中性、容量上限）在段内各自满足、全局违反。第三错误是缓存不一致：特征缓存键漏掉数据版本，数据修正后旧特征照用，「修了 bug 结果不变」。三个错误共享一个根源：把并行当成纯计算问题，忘了它是数据一致性问题。</p><h3 id="切分维度的选择" tabindex="-1">切分维度的选择 <a class="header-anchor" href="#切分维度的选择" aria-label="Permalink to &quot;切分维度的选择&quot;">​</a></h3><p>任务有三个可切维度。按参数切：网格各点独立，天然并行，但同点内仍受单任务时长限制。按时间切：走窗各段独立，适合样本外协议，但必须处理持有期跨界与状态初始化。按标的切：只在策略是无截面约束的纯时序时合法。多数研究取「参数为主、时间为辅」的两级切分；切法本身要作为实验元数据登记，因为切法影响结果的可比性。</p>',7)),(B(),t(i,null,{default:a(()=>[o(A,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E6%8C%89%E5%8F%82%E6%95%B0%E5%88%87%3A%20%E7%BD%91%E6%A0%BC%E5%90%84%E7%82%B9%E7%8B%AC%E7%AB%8B%22%5D%20--%3E%20PO%5B%22%E9%99%B7%E9%98%B1%3A%20%E5%8D%95%E7%82%B9%E4%BB%BB%E5%8A%A1%E4%BB%8D%E5%8F%AF%E8%83%BD%E5%A4%AA%E6%85%A2%22%5D%0A%20%20T%5B%22%E6%8C%89%E6%97%B6%E9%97%B4%E5%88%87%3A%20%E8%B5%B0%E7%AA%97%E5%90%84%E6%AE%B5%E7%8B%AC%E7%AB%8B%22%5D%20--%3E%20TO%5B%22%E9%99%B7%E9%98%B1%3A%20%E6%8C%81%E6%9C%89%E6%9C%9F%E8%B7%A8%E6%AE%B5%E7%95%8C%20%E4%B8%A2%E5%A4%B1%E6%88%96%E9%87%8D%E5%A4%8D%22%5D%0A%20%20T%20--%3E%20TI%5B%22%E9%99%B7%E9%98%B1%3A%20%E6%AF%8F%E6%AE%B5%E7%8A%B6%E6%80%81%E8%A6%81%E9%87%8D%E6%96%B0%E5%88%9D%E5%A7%8B%E5%8C%96%22%5D%0A%20%20S%5B%22%E6%8C%89%E6%A0%87%E7%9A%84%E5%88%87%3A%20%E5%90%84%E8%82%A1%E7%A5%A8%E7%8B%AC%E7%AB%8B%E5%BA%8F%E5%88%97%22%5D%20--%3E%20SO%5B%22%E9%99%B7%E9%98%B1%3A%20%E8%A1%8C%E4%B8%9A%E4%B8%AD%E6%80%A7%20%2F%20%E5%AE%B9%E9%87%8F%E7%AD%89%E5%85%A8%E5%B1%80%E7%BA%A6%E6%9D%9F%E8%A2%AB%E8%BF%9D%E5%8F%8D%22%5D%0A%20%20P%20--%20%22%E4%B8%BB%E6%B5%81%3A%20%E5%8F%82%E6%95%B0%E4%B8%BA%E4%B8%BB%E6%97%B6%E9%97%B4%E4%B8%BA%E8%BE%85%22%20--%3E%20META%5B%22%E5%88%87%E6%B3%95%E5%86%99%E5%85%A5%E5%AE%9E%E9%AA%8C%E5%85%83%E6%95%B0%E6%8D%AE%22%5D%0A%20%20T%20--%3E%20META%0A%20%20META%20--%3E%20NOTE%5B%22%E6%88%AA%E9%9D%A2%E5%88%87%E4%BB%85%E9%99%90%E6%97%A0%E7%BB%84%E5%90%88%E7%BA%A6%E6%9D%9F%E7%9A%84%E7%BA%AF%E6%97%B6%E5%BA%8F%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e('<p><span class="marginnote">加速比的上限常在存储而非算力：数百 worker 并发扫同一张 tick 表，瓶颈是对象存储带宽与缓存命中率。扩 worker 之前先看 IO 等待占比，是分布式回测的第一课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>架构四件套。<strong>调度器</strong>：把任务（参数点、时间段、策略版本、数据版本、规则版本）入队，任务描述里显式钉住数据版本与清洗规则版本——沿用<a href="/quant/de-data-versioning">数据版本化</a>的三要素哈希，任何 worker 不许自行解析「最新」。<strong>无状态 worker</strong>：拉任务、挂载数据版本、跑、写结果，崩了重跑不影响别人；本地状态只是缓存。<span class="marginnote">术语翻译：无状态就是「worker 不记事」——它自己不保存任何别人依赖的东西，任务的所有信息（参数、数据版本、规则）都由调度器发给它。好处是某台机器挂了，把任务丢给任何一台空闲机器重跑即可，结果完全一样；有状态的话，挂掉就等于丢工作。</span><strong>数据平面</strong>：点时库与特征缓存按（数据版本、日期段）键控，任务间共享只读挂载；这是 append-only 存储的直接红利。<strong>结果登记</strong>：每个结果带完整血缘（任务描述、引擎版本、数据哈希）入台账，供复盘与聚合，口径与<a href="/quant/research-postmortem">复盘</a>一致。聚合层在全部叶子完成后做全局约束与汇总统计，不许在 worker 内偷偷做全局判断。</p>',3)),(B(),t(i,null,{default:a(()=>[o(A,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20EXP%5B%22%E5%AE%9E%E9%AA%8C%E6%8F%8F%E8%BF%B0%EF%BC%9A%E5%8F%82%E6%95%B0%E7%BD%91%E6%A0%BC%20%2B%20%E7%89%88%E6%9C%AC%E4%B8%89%E5%85%83%E7%BB%84%22%5D%20--%3E%20SCH%5B%22%E8%B0%83%E5%BA%A6%E5%99%A8%EF%BC%9A%E4%BB%BB%E5%8A%A1%E5%85%A5%E9%98%9F%22%5D%0A%20%20SCH%20--%3E%20W1%5B%22worker%EF%BC%9A%E6%8C%82%E8%BD%BD%E6%95%B0%E6%8D%AE%E7%89%88%E6%9C%AC%EF%BC%8C%E8%B7%91%E5%88%87%E7%89%87%22%5D%0A%20%20SCH%20--%3E%20W2%5B%22worker%EF%BC%9A%E5%90%8C%E4%B8%8A%EF%BC%8C%E6%97%A0%E6%9C%AC%E5%9C%B0%E7%9C%9F%E7%9B%B8%22%5D%0A%20%20SCH%20--%3E%20W3%5B%22worker%EF%BC%9A%E5%B4%A9%E4%BA%86%E9%87%8D%E8%B7%91%22%5D%0A%20%20PIT%5B%22%E7%82%B9%E6%97%B6%E5%BA%93%EF%BC%9A%E5%94%AF%E4%B8%80%20as-of%20%E5%87%BD%E6%95%B0%22%5D%20--%3E%20W1%0A%20%20PIT%20--%3E%20W2%0A%20%20PIT%20--%3E%20W3%0A%20%20W1%20--%3E%20REG%5B%22%E7%BB%93%E6%9E%9C%E7%99%BB%E8%AE%B0%EF%BC%9A%E5%AE%8C%E6%95%B4%E8%A1%80%E7%BC%98%E5%85%A5%E5%8F%B0%E8%B4%A6%22%5D%0A%20%20W2%20--%3E%20REG%0A%20%20W3%20--%3E%20REG%0A%20%20REG%20--%3E%20AGG%5B%22%E8%81%9A%E5%90%88%EF%BC%9A%E5%85%A8%E5%B1%80%E7%BA%A6%E6%9D%9F%E4%B8%8E%E6%B1%87%E6%80%BB%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>这套架构的机制核心是「一致性由数据版本承担，不由任务时刻承担」。任务钉死版本后，排队、重跑、复算都与队内他人无关，因为大家读同一份不可变字节；数据修正意味着发新版本、新实验，旧结果自动归档而非被改写。Amdahl 的老话在这里换个读法：不可并行的是数据准备与全局聚合，它们是串行段；把特征物化前置成批量、把聚合做成叶子任务的浅层合并，串行段越短，集群规模才越有用。反过来，容忍数据漂的集群会把方差引入实验：同一网格两次扫描结果不同，研究者会把噪声当成参数敏感性——这是分布式回测特有的伪发现来源，单机时代不存在。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课只管「把同一个回测跑一万遍」的架构；回测引擎内部的事件循环、成交模拟是下一门回测框架设计课程的对象，本课不重讲。分布式也不免费：任务粒度太细，调度与 IO 开销吃掉收益；粒度太粗，故障重跑代价大。切分粒度应让单任务落在分钟级。<span class="marginnote">数字实例：Amdahl 定律说，若串行段（数据准备、全局聚合）占 10%，就算加到无穷多台机器，总加速也超不过 10 倍——100 台机器的实际加速只有约 9.2 倍。所以缩短串行段（特征前置物化、浅层聚合）比堆机器更划算。</span>最后，架构不能修复坏实验：并行让多重检验更便宜，\\(N\\) 的台账与折价纪律反而更要严格执行，见<a href="/quant/backtest-overfitting">回测过拟合</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>分布式回测的第一风险是数据漂移，第一纪律是任务钉版本三元组。</li><li>切分三维：参数、时间、截面；切法本身是实验元数据。</li><li>时间切段必须处理持有期跨界，截面切段不能承载全局组合约束。</li><li>无状态 worker 加共享只读数据平面，一致性由数据版本承担。</li><li>瓶颈先查存储带宽与缓存命中，再谈加机器。</li><li>出处：Amdahl, AFIPS 1967；站内<a href="/quant/de-data-versioning">数据版本化</a>、<a href="/quant/backtest-vectorization">回测向量化</a>与<a href="/quant/backtest-overfitting">回测过拟合</a>各课。</li></ul>',6))])}const F=n(d,[["render",C]]);export{m as __pageData,F as default};
